<?php
require_once __DIR__.'/../../includes/bootstrap.php';$u=require_login();header('Content-Type: application/json; charset=utf-8');
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'message'=>'POST required.']);exit;}
try{verify_csrf($_POST['csrf']??'');$bid=(int)($_POST['booking_id']??0);$date=trim($_POST['target_date']??'');$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)throw new RuntimeException('Invalid target date.');$pdo=db();$q=$pdo->prepare('SELECT b.id,b.status,e.title,e.start_at,e.end_at FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.id=? AND b.user_id=?');$q->execute([$bid,$u['id']]);$b=$q->fetch();if(!$b||!in_array($b['status'],['pending_review','pending_info','confirmed'],true))throw new RuntimeException('This booking cannot be moved.');$oldS=new DateTime($b['start_at']);$oldE=new DateTime($b['end_at']);if($date===$oldS->format('Y-m-d'))throw new RuntimeException('Choose a different date.');$pending=$pdo->prepare("SELECT COUNT(*) FROM booking_change_requests WHERE booking_id=? AND status='pending'");$pending->execute([$bid]);if((int)$pending->fetchColumn())throw new RuntimeException('A change request is already awaiting review.');$newS=new DateTime($date.' '.$oldS->format('H:i:s'));$newE=(clone $newS)->modify('+'.($oldE->getTimestamp()-$oldS->getTimestamp()).' seconds');$pdo->prepare('INSERT INTO booking_change_requests(booking_id,requested_by,reason,proposed_start_at,proposed_end_at) VALUES(?,?,?,?,?)')->execute([$bid,$u['id'],'Date change requested by dragging the event on the user calendar.',$newS->format('Y-m-d H:i:s'),$newE->format('Y-m-d H:i:s')]);audit('calendar_date_change_requested','booking',$bid,['start_at'=>$b['start_at']],['start_at'=>$newS->format('Y-m-d H:i:s')]);echo json_encode(['ok'=>true,'message'=>'Date-change request sent to Management. The calendar date remains unchanged until approval.']);}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'message'=>$e->getMessage()]);}
